#ifndef CELLPREDICTOR_H
#define CELLPREDICTOR_H

#include <cstddef>
#include <cstdint>
#include <map>
#include <string>
#include <vector>

#include "cellnet.h"

/**
 * @brief Property predictor of the Neural tab: voxel cell 64^3 + material -> the 24 properties of a request.
 *
 * The third network of the cell generator (cellgen: predictor.py, train_pred.py). It
 * answers at once what the FFT solver answers in minutes, with an error: on cells of
 * the dataset it has not seen the moduli are typically off by 7 %, on cells the
 * diffusion network generated by 12 % (run pred1; the note of the weights file says
 * what was measured). It does not replace the solve, it says what to expect of it.
 *
 * Two parts, both in the exported file (tools/neural/export_cell_predictor.py):
 *   the encoder of the cell autoencoder: cell 64^3 -> code 16 x 16 x 16 x 4, the same
 *   code the diffusion network writes and CellDecoder reads;
 *   the predictor: code + noise level of the code + material -> 24 numbers. It is the
 *   compressing half of the diffusion U-Net in a reduced form (16^3 -> 8^3 -> 4^3,
 *   mean over the grid, two fully connected layers). The noise level is an input
 *   because the network was also trained on noised codes; a code of a finished cell
 *   has level 0.
 *
 * Plain C++ on the layers of cellnet.h (no Qt, no ML library). The file is 12 MB and
 * is read whole by load(). encode(), scaled() and predict() keep no state: they may
 * be called from a worker thread while another thread reads the object.
 *
 * Arrays are flat, the first index slowest: a cell is [i][j][k] with i, j, k the
 * program's voxel axes x, y, z (what CellDecoder::decode returns), a code [channel][i][j][k].
 */
class CellPredictor
{
public:
    /// One predicted property and the constants the training scaled it with (as CellDiffusion::Target).
    struct Target {
        std::string key;        ///< "Ex", "density", ...: the names of cellgen props.KEYS
        int kind = 0;           ///< 0 as is, 1 ln(x), 2 ln(1 + x), 3 ln(x / E of the material)
        float lo = 0, hi = 0;   ///< range of the training cells, in the scale of `kind`
        float mean = 0, std = 1;
    };

    /// Read the exported file. False (and *error) when it is not one.
    bool load(const std::string& path, std::string* error = nullptr);
    bool loaded() const { return m_loaded; }

    const std::string& path() const { return m_path; }
    /// "pred1 step 14000": the training run the weights come from.
    const std::string& name() const { return m_name; }
    /// What was measured on this model (written at export).
    const std::string& note() const { return m_note; }
    size_t weightCount() const { return m_weights; }
    /// Voxels per edge of the cell it reads.
    int cellSize() const { return m_cellN; }
    int codeChannels() const { return m_zc; }
    int codeSize() const { return m_codeN; }
    size_t codeLength() const { return size_t(m_zc) * m_codeN * m_codeN * m_codeN; }
    const std::vector<Target>& targets() const { return m_targets; }

    /**
     * The code of a cell (cellSize()^3 values, nonzero = solid) in the scale of the
     * diffusion network: zero mean and unit spread per channel. Empty when the cell
     * has another size.
     */
    std::vector<float> encode(const std::vector<uint8_t>& cell) const;
    /**
     * The properties in the scale of the training (z-scores, one per target) for a
     * code in the network's scale at a noise level (0 = the code of a finished cell).
     * Material: Poisson's ratio, and E across the layers / E along them.
     */
    std::vector<float> scaled(const std::vector<float>& code, int level, double nu, double aniso) const;
    /// A z-score of target `index` in the units of the dataset: moduli in Pa for a material of eGpa, the rest as it is.
    double value(size_t index, float scaled, double eGpa) const;
    /// The properties of a cell by their keys, in the units of the dataset (moduli in Pa). Empty when it cannot be told.
    std::map<std::string, double> predict(const std::vector<uint8_t>& cell, double eGpa, double nu, double aniso) const;

private:
    struct Down { bool isConv = false; cellnet::Res res; cellnet::Attn attn; cellnet::Conv conv; };

    template <class Source> void build(Source& src);

    bool m_loaded = false;
    std::string m_path, m_name, m_note;
    size_t m_weights = 0;
    int m_cellN = 0, m_zc = 0, m_codeN = 0, m_stem = 1, m_groups = 8, m_heads = 4, m_nb = 0, m_hidden = 0;
    std::vector<int> m_encCh, m_encBlocks, m_ch, m_attn;
    std::vector<Target> m_targets;
    float m_matMean[2] = { 0, 0 }, m_matStd[2] = { 1, 1 };
    std::vector<float> m_codeMean, m_codeStd;
    // The encoder, in the order of its forward pass.
    cellnet::Conv m_encInp, m_encOut;
    std::vector<cellnet::Conv> m_encDown;              // the stride-2 convolution before level 1, 2, ...
    std::vector<std::vector<cellnet::Res>> m_encRes;   // the blocks of every level
    cellnet::Norm m_encNorm;
    // The predictor.
    cellnet::Linear m_time0, m_time1, m_mat0, m_mat1, m_head0, m_head1;
    cellnet::Conv m_inp;
    std::vector<Down> m_down;
    cellnet::Norm m_norm;
};

#endif // CELLPREDICTOR_H
